// All times are in Ma (millions of years before the explicit reference year below).
// Positive values are earlier, zero is the reference year, and negative values are later.
// Calendar-dated entries use this fixed snapshot so their displayed years cannot drift.
export const TIMELINE_REFERENCE_YEAR = 2026;

const ce = (year) => (TIMELINE_REFERENCE_YEAR - year) / 1_000_000;
const bce = (year) => (TIMELINE_REFERENCE_YEAR + year - 1) / 1_000_000;

